package edu.nexus.work;
import java.security.Principal;
import java.time.LocalDate;
import java.util.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api")
class WorkspaceController {
 final JdbcTemplate db;final PasswordEncoder encoder;final OperationalService operations;
 WorkspaceController(JdbcTemplate db,PasswordEncoder encoder,OperationalService operations){this.db=db;this.encoder=encoder;this.operations=operations;}
 @GetMapping("/csrf") Map<String,String> csrf(CsrfToken token){return Map.of("token",token.getToken());}
 Map<String,Object> actor(Principal principal){return db.queryForMap("select id,username,role from app_user where username=? and enabled=true",principal.getName());}
 void access(UUID id,Map<String,Object> user){if(!Boolean.TRUE.equals(db.queryForObject("select exists(select 1 from project p where p.id=? and (p.owner_id=? or ?='ADMIN' or exists(select 1 from project_member m where m.project_id=p.id and m.user_id=?)))",Boolean.class,id,user.get("id"),user.get("role"),user.get("id"))))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Project unavailable");}
 void owner(UUID id,Map<String,Object> user){access(id,user);if(!user.get("role").equals("ADMIN")&&!db.queryForObject("select owner_id from project where id=?",UUID.class,id).equals(user.get("id")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Project owner required");}
 void writable(UUID id){if(Boolean.TRUE.equals(db.queryForObject("select archived from project where id=? for share",Boolean.class,id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Project is archived");}
 void audit(Principal actor,String event,UUID id,String detail){db.update("insert into business_audit(actor,action,entity_id,detail) values (?,?,?,?)",actor.getName(),event,id,detail);operations.event(event+" "+id);}
 @GetMapping("/me") Map<String,Object> me(Authentication a){var user=actor(a);return Map.of("id",user.get("id"),"username",a.getName(),"role",user.get("role"));}
 @GetMapping("/projects") List<Map<String,Object>> projects(Principal p){var a=actor(p);return db.queryForList("select p.*,u.username as owner_name,(select count(*) from task t where t.project_id=p.id) as task_count from project p join app_user u on u.id=p.owner_id where p.owner_id=? or ?='ADMIN' or exists(select 1 from project_member m where m.project_id=p.id and m.user_id=?) order by p.created_at desc limit 200",a.get("id"),a.get("role"),a.get("id"));}
 record ProjectInput(@NotBlank @Size(max=160)String name,@Size(max=10000)String description) {}
 @PostMapping("/projects") @Transactional Map<String,Object> createProject(@Valid @RequestBody ProjectInput input,Principal p){var a=actor(p);UUID id=UUID.randomUUID();db.update("insert into project(id,name,description,owner_id) values (?,?,?,?)",id,input.name().trim(),Objects.requireNonNullElse(input.description(),""),a.get("id"));db.update("insert into project_member values (?,?)",id,a.get("id"));audit(p,"PROJECT_CREATED",id,"Project created");return db.queryForMap("select * from project where id=?",id);}
 record ProjectUpdate(@NotBlank @Size(max=160)String name,@Size(max=10000)String description,boolean archived,@Min(0)int version) {}
 @PostMapping("/projects/{id}/update") @Transactional Map<String,Object> updateProject(@PathVariable UUID id,@Valid @RequestBody ProjectUpdate input,Principal p){owner(id,actor(p));if(db.update("update project set name=?,description=?,archived=?,version=version+1 where id=? and version=?",input.name().trim(),Objects.requireNonNullElse(input.description(),""),input.archived(),id,input.version())!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Project changed; refresh");audit(p,"PROJECT_UPDATED",id,"Project details or archive status changed");return db.queryForMap("select * from project where id=?",id);}
 @GetMapping("/projects/{id}/members") List<Map<String,Object>> members(@PathVariable UUID id,Principal p){access(id,actor(p));return db.queryForList("select u.id,u.username,u.enabled from project_member m join app_user u on u.id=m.user_id where m.project_id=? order by u.username",id);}
 record Membership(@NotBlank @Size(max=80)String username) {}
 @PostMapping("/projects/{id}/members") @Transactional Map<String,Boolean> addMember(@PathVariable UUID id,@Valid @RequestBody Membership input,Principal p){owner(id,actor(p));var users=db.queryForList("select id from app_user where username=? and enabled=true",input.username());if(users.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"User unavailable");db.update("insert into project_member values (?,?) on conflict do nothing",id,users.getFirst().get("id"));audit(p,"MEMBER_ADDED",id,"Project membership updated");return Map.of("added",true);}
 @GetMapping("/projects/{id}/tasks") Map<String,Object> tasks(@PathVariable UUID id,@RequestParam(defaultValue="50")int limit,@RequestParam(defaultValue="0")int offset,Principal p){access(id,actor(p));if(limit<1||limit>200||offset<0||offset>100000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid page");var items=db.queryForList("select t.*,u.username as assignee_name from task t left join app_user u on u.id=t.assignee_id where t.project_id=? order by t.updated_at desc,t.id limit ? offset ?",id,limit,offset);return Map.of("items",items,"total",db.queryForObject("select count(*) from task where project_id=?",Long.class,id),"offset",offset,"limit",limit);}
 record TaskInput(@NotBlank @Size(max=200)String title,@Size(max=20000)String description,@NotNull @Pattern(regexp="TODO|IN_PROGRESS|DONE")String status,@NotNull @Pattern(regexp="LOW|MEDIUM|HIGH")String priority,UUID assigneeId,LocalDate dueDate,@Min(0)int version) {}
 void assignee(UUID project,UUID user){if(user!=null&&!Boolean.TRUE.equals(db.queryForObject("select exists(select 1 from project_member m join app_user u on u.id=m.user_id where m.project_id=? and m.user_id=? and u.enabled=true)",Boolean.class,project,user)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Assignee must be an active project member");}
 @PostMapping("/projects/{id}/tasks") @Transactional Map<String,Object> createTask(@PathVariable UUID id,@Valid @RequestBody TaskInput input,Principal p){var a=actor(p);access(id,a);writable(id);assignee(id,input.assigneeId());UUID task=UUID.randomUUID();db.update("insert into task(id,project_id,title,description,status,priority,assignee_id,due_date,created_by) values (?,?,?,?,?,?,?,?,?)",task,id,input.title().trim(),Objects.requireNonNullElse(input.description(),""),input.status(),input.priority(),input.assigneeId(),input.dueDate(),a.get("id"));audit(p,"TASK_CREATED",task,"Task created");return db.queryForMap("select * from task where id=?",task);}
 @PostMapping("/tasks/{id}/update") @Transactional Map<String,Object> updateTask(@PathVariable UUID id,@Valid @RequestBody TaskInput input,Principal p){var rows=db.queryForList("select project_id from task where id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Task unavailable");UUID project=(UUID)rows.getFirst().get("project_id");access(project,actor(p));writable(project);assignee(project,input.assigneeId());if(db.update("update task set title=?,description=?,status=?,priority=?,assignee_id=?,due_date=?,version=version+1,updated_at=now() where id=? and version=?",input.title().trim(),Objects.requireNonNullElse(input.description(),""),input.status(),input.priority(),input.assigneeId(),input.dueDate(),id,input.version())!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Task changed; refresh before editing");audit(p,"TASK_UPDATED",id,"Task details changed");return db.queryForMap("select * from task where id=?",id);}
 @GetMapping("/projects/{id}/audit") List<Map<String,Object>> history(@PathVariable UUID id,Principal p){access(id,actor(p));return db.queryForList("select a.* from business_audit a where a.entity_id=? or a.entity_id in (select id from task where project_id=?) order by a.at desc limit 200",id,id);}
 record UserInput(@Pattern(regexp="[a-zA-Z0-9_.-]{3,80}")@NotNull String username,@Size(min=12,max=72)@NotNull String password,@Pattern(regexp="ADMIN|MEMBER")@NotNull String role) {}
 @GetMapping("/admin/users") List<Map<String,Object>> users(){return db.queryForList("select id,username,role,enabled,created_at from app_user order by username");}
 @PostMapping("/admin/users") @Transactional Map<String,Object> createUser(@Valid @RequestBody UserInput input,Principal p){UUID id=UUID.randomUUID();db.update("insert into app_user(id,username,password,role) values (?,?,?,?)",id,input.username(),encoder.encode(input.password()),input.role());audit(p,"USER_CREATED",id,"Account provisioned");return Map.of("id",id,"username",input.username(),"role",input.role());}
 record PasswordChange(@NotBlank String currentPassword,@NotNull @Size(min=12,max=72)String newPassword) {}
 @PostMapping("/password") @Transactional Map<String,Boolean> password(@Valid @RequestBody PasswordChange input,Principal p){String old=db.queryForObject("select password from app_user where username=?",String.class,p.getName());if(!encoder.matches(input.currentPassword(),old))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect");db.update("update app_user set password=? where username=?",encoder.encode(input.newPassword()),p.getName());audit(p,"PASSWORD_CHANGED",(UUID)actor(p).get("id"),"Password changed by account owner");return Map.of("changed",true);}
 record Maintenance(@NotNull Boolean enabled,@NotBlank @Size(max=500)String reason) {}
 @GetMapping("/admin/operations") Map<String,Object> state(){return operations.state();}
 @PostMapping("/admin/maintenance") Map<String,Object> maintenance(@Valid @RequestBody Maintenance input,Principal p){return operations.change(input.enabled(),input.reason(),p.getName());}
 @GetMapping("/admin/audit") List<Map<String,Object>> audit(){return db.queryForList("select * from business_audit order by id desc limit 200");}
}
